/** Cross-kernel bridge names shared by preludes and host adapters. */
/** Canonical oh-my-pi agent bridge tool name. */
export const RESERVED_AGENT_TOOL = "__agent__" as const;
/** ADAPTATION: senpi delegates output through a reserved kernel-side tool name. */
export const RESERVED_OUTPUT_TOOL = "__output__" as const;
/** ADAPTATION: senpi resolves tool parameter schemas through a reserved kernel-side tool name. */
export const RESERVED_SCHEMA_TOOL = "__schema__" as const;
/** Canonical oh-my-pi eval-timeout pause operation. */
export const TIMEOUT_PAUSE_OP = "timeout-pause" as const;
/** Canonical oh-my-pi eval-timeout resume operation. */
export const TIMEOUT_RESUME_OP = "timeout-resume" as const;
/** Status op the JS worker emits the moment it receives `interrupt`; proves its event loop is not blocked. */
export const INTERRUPT_ACK_OP = "interrupt-ack" as const;

import { homedir } from "node:os";
import type { EvalLanguage, EvalRuntimeInfo } from "./types.ts";

const MAX_BADGE_PATH_CODE_POINTS = 40;
const ELLIPSIS = "\u2026";

/**
 * One-line runtime badge for eval headers, e.g. "3.14.7, ~/.venv/bin/python3"
 * or "node 26.7.0, /opt/…/bin/node". The js language always carries the
 * runtime name because node and bun are otherwise indistinguishable.
 */
export function formatRuntimeBadge(language: EvalLanguage, runtime: EvalRuntimeInfo, home: string = homedir()): string {
	const label = language === "js" ? `${runtime.name} ${runtime.version}` : runtime.version;
	if (runtime.path === undefined || runtime.path.length === 0) return label;
	return `${label}, ${minifyPath(runtime.path, home)}`;
}

/** Home-contracts and middle-truncates a path so header badges stay short. */
export function minifyPath(path: string, home: string = homedir()): string {
	const contracted = contractHome(path, home);
	if (codePointLength(contracted) <= MAX_BADGE_PATH_CODE_POINTS) return contracted;
	const separator = contracted.includes("/") ? "/" : "\\";
	const segments = contracted.split(separator).filter((segment) => segment.length > 0);
	const head = contracted.startsWith(separator) ? `${separator}${segments[0] ?? ""}` : (segments[0] ?? "");
	const tail: string[] = [];
	for (let index = segments.length - 1; index >= 1; index -= 1) {
		const attempt = joinTruncated(head, [segments[index] ?? "", ...tail], separator);
		if (codePointLength(attempt) > MAX_BADGE_PATH_CODE_POINTS) break;
		tail.unshift(segments[index] ?? "");
	}
	if (tail.length > 0) return joinTruncated(head, tail, separator);
	const suffix = [...contracted].slice(-(MAX_BADGE_PATH_CODE_POINTS - 1)).join("");
	return `${ELLIPSIS}${suffix}`;
}

function joinTruncated(head: string, tail: readonly string[], separator: string): string {
	return `${head}${separator}${ELLIPSIS}${separator}${tail.join(separator)}`;
}

function contractHome(path: string, home: string): string {
	if (home.length === 0) return path;
	if (path === home) return "~";
	if (path.startsWith(`${home}/`) || path.startsWith(`${home}\\`)) return `~${path.slice(home.length)}`;
	return path;
}

function codePointLength(text: string): number {
	return [...text].length;
}

export { TIMEOUT_PAUSE_OP, TIMEOUT_RESUME_OP } from "../bridge/reserved.ts";

import type { TimeoutPauseHandle } from "./idle-timeout.ts";

export async function withBridgeTimeoutPause<T>(
	watchdog: TimeoutPauseHandle | undefined,
	operation: () => Promise<T>,
): Promise<T> {
	if (watchdog === undefined) return operation();
	watchdog.pause();
	try {
		return await operation();
	} finally {
		watchdog.resume();
	}
}

import type { StreamFn } from "./types.ts";

let defaultStreamFn: StreamFn | undefined;

/**
 * Configure the fallback used by Agent and low-level loops when callers omit streamFn.
 *
 * Hosts that provide a default model runtime can install its stream function here
 * without making pi-agent-core depend on a provider catalog or compatibility layer.
 */
export function setDefaultStreamFn(streamFn: StreamFn | undefined): void {
	defaultStreamFn = streamFn;
}

export function getDefaultStreamFn(): StreamFn {
	if (!defaultStreamFn) {
		throw new Error("No default stream function configured. Pass streamFn explicitly or call setDefaultStreamFn().");
	}
	return defaultStreamFn;
}

export { withEmptyAssistantRecovery } from "./empty-assistant-recovery.ts";

import type { Context } from "../context.ts";
import type { ExecutionEnv } from "../types.ts";
import { getOrThrow } from "../types.ts";

const UNICODE_SPACES = /[\u00A0\u2000-\u200A\u202F\u205F\u3000]/g;
const NARROW_NO_BREAK_SPACE = "\u202F";

function normalizeToolPath(path: string): string {
	const normalized = path.replace(UNICODE_SPACES, " ");
	return normalized.startsWith("@") ? normalized.slice(1) : normalized;
}

export async function resolveToolPath(env: ExecutionEnv, path: string, context: Context): Promise<string> {
	return getOrThrow(await env.absolutePath(normalizeToolPath(path), context));
}

export async function resolveReadToolPath(env: ExecutionEnv, path: string, context: Context): Promise<string> {
	const resolved = await resolveToolPath(env, path, context);
	const variants = [
		resolved,
		resolved.replace(/ (AM|PM)\./gi, `${NARROW_NO_BREAK_SPACE}$1.`),
		resolved.normalize("NFD"),
		resolved.replace(/'/g, "\u2019"),
		resolved.normalize("NFD").replace(/'/g, "\u2019"),
	];

	for (const variant of new Set(variants)) {
		if (getOrThrow(await env.exists(variant, context))) return variant;
	}
	return resolved;
}

import { envValue } from "./brand.ts";

const PREFER_STRICT_TOOL_SAMPLING = { type: "json_schema", strict: "prefer" } as const;
export function areExperimentalFeaturesEnabled(): boolean {
	return envValue("EXPERIMENTAL") === "1";
}

export function getExperimentalToolSampling() {
	return areExperimentalFeaturesEnabled() ? PREFER_STRICT_TOOL_SAMPLING : undefined;
}

// Releases a subscription at most once. Child subscriptions are released by two owners - the caller
// that subscribed (a task_output wait may release on settle AND on abort) and the manager's own
// sweep - so the raw handle detach must never run twice.
export function onceOnly(release: () => void): () => void {
  let released = false
  return () => {
    if (released) return
    released = true
    release()
  }
}

export type ExecutionMode = "in-process" | "process"

export type ExecutionModeSources = {
  readonly specMode?: ExecutionMode
  readonly agentMode?: ExecutionMode
  readonly configMode?: ExecutionMode
}

// Precedence: spec.execution_mode ?? agentDef.executionMode ?? omo.json task.default_execution_mode
// ?? "in-process".
export function resolveExecutionMode(sources: ExecutionModeSources): ExecutionMode {
  return sources.specMode ?? sources.agentMode ?? sources.configMode ?? "in-process"
}

import type { ToolDefinition } from "@code-yeongyu/senpi"

// Runtime-only provenance: a persisted tool name or a parent's scheduler cannot impersonate
// the engine-created yield wrapper when member tools are reconstructed on cold revival.
const yieldTools = new WeakSet<ToolDefinition>()
export function markWorkpoolYieldTool(tool: ToolDefinition): ToolDefinition { yieldTools.add(tool); return tool }
export function isWorkpoolYieldTool(tool: ToolDefinition): boolean { return yieldTools.has(tool) }

import type { OmoTaskSettings } from "@oh-my-opencode/omo-config-core"

export type WaitBounds = OmoTaskSettings["wait"]

// Codex wait contract (config min/default/max): an omitted timeout falls back to default_ms; any
// supplied value is clamped into [min_ms, max_ms]. Boundary intent (defaults 5000/60000/600000):
// 4999 -> 5000, 999999 -> 600000.
export function clampWaitTimeout(requested: number | undefined, bounds: WaitBounds): number {
  if (requested === undefined) return bounds.default_ms
  if (requested < bounds.min_ms) return bounds.min_ms
  if (requested > bounds.max_ms) return bounds.max_ms
  return requested
}

import type { RunnerFailure } from "./child-handle"

export class RunnerError extends Error {
  readonly #brand = true
  readonly failure: RunnerFailure

  constructor(failure: RunnerFailure) {
    super(failure.message, failure.cause === undefined ? undefined : { cause: failure.cause })
    this.name = "RunnerError"
    this.failure = failure
  }

  static is(value: unknown): value is RunnerError {
    try {
      return typeof value === "object" && value !== null && #brand in value
    } catch {
      return false
    }
  }
}
